import re, html
from html.parser import HTMLParser

class P(HTMLParser):
    def __init__(self):
        super().__init__()
        self.out=[]
        self.skip=0
        self.tag=None
    def handle_starttag(self,tag,attrs):
        if tag in ('script','style','noscript','svg','head'): self.skip+=1
        self.tag=tag
        if tag in ('p','div','li','h1','h2','h3','h4','br','tr'):
            self.out.append('\n')
        if tag in ('h1','h2','h3','h4'):
            self.out.append(f'\n[{tag.upper()}] ')
    def handle_endtag(self,tag):
        if tag in ('script','style','noscript','svg','head') and self.skip>0: self.skip-=1
    def handle_data(self,data):
        if self.skip==0:
            self.out.append(data)

for name in ('terms','privacy','usage'):
    p=P()
    p.feed(open(name+'.html',encoding='utf-8',errors='ignore').read())
    text=''.join(p.out)
    text=re.sub(r'\n\s*\n+','\n',text)
    text=re.sub(r'[ \t]+',' ',text)
    open(name+'.txt','w').write(text)
    print(name, len(text))
EOF

