const fs=require('fs');
function strip(html){
  let t=html
    .replace(/<script[\s\S]*?<\/script>/gi,'')
    .replace(/<style[\s\S]*?<\/style>/gi,'')
    .replace(/<svg[\s\S]*?<\/svg>/gi,'')
    .replace(/<(h[1-4])[^>]*>/gi,'\n[[$1]] ')
    .replace(/<\/(p|div|li|h[1-4]|tr|br)>/gi,'\n')
    .replace(/<br[^>]*>/gi,'\n')
    .replace(/<[^>]+>/g,'')
    .replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>')
    .replace(/&#x27;|&#39;|&rsquo;/g,"'").replace(/&quot;|&ldquo;|&rdquo;/g,'"')
    .replace(/&nbsp;/g,' ').replace(/&#(\d+);/g,(m,n)=>String.fromCharCode(n))
    .replace(/[ \t]+/g,' ')
    .replace(/\n\s*\n+/g,'\n');
  return t;
}
